$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','Synthetic'),('b','Other');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','member',1),('foreign','b','member',1),('member','a','member',0)");$f=new Finance($db,'admin');$service=new OutgoingEInvoice($db,'admin');$key=fn()=>bin2hex(random_bytes(16));$data=['kind'=>'income','description'=>'Test service','counterparty'=>'Example buyer','category'=>'general','document_date'=>'2026-09-08','due_date'=>'2026-09-22','positions'=>[['description'=>'Agreed service package','amount'=>'119','tax_rate'=>'19','sphere'=>'','account'=>'']]];$id=$f->createEntry($data,$key());$fields=['confirmed'=>'1','invoice_number'=>'TEST-2026-17','buyer_reference'=>'TEST-BUYER','seller_name'=>'Fiktiver Musterverein e.V.','seller_street'=>'Musterweg 1','seller_city'=>'Musterstadt','seller_postcode'=>'12345','seller_email'=>'seller@example.org','seller_contact'=>'Rechnungsstelle','seller_phone'=>'+49 123 456789','seller_register'=>'VR 12345 Musterstadt','seller_tax_number'=>'123/456/78901','buyer_name'=>'Fiktive Kundengesellschaft','buyer_street'=>'Testweg 2','buyer_city'=>'Beispielstadt','buyer_postcode'=>'23456','buyer_email'=>'buyer@example.org','delivery_date'=>'2026-09-07','iban'=>'DE89370400440532013000'];$n=0;function check($v,$l){global $n;if(!$v)throw new RuntimeException($l);++$n;echo "PASS $l\n";}function denied($f,$l){try{$f();}catch(DomainException){check(true,$l);return;}throw new RuntimeException($l);}
