$cancelled=$f->createEntry($data,$key());$f->cancel($cancelled,1);denied(fn()=>$service->source($cancelled),'actual cancelled entry rejected');$paid=$f->createEntry($data,$key());$account=$f->createAccount('Synthetic bank','offline','0','2026-01-01');$f->recordPayment($paid,1,$account,'2026-09-08');check($service->source($paid)['entry']['allocated_cents']===11900,'paid entry uses actual allocated amount');$f->reverse($paid,(int)$f->entry($paid)['version'],'2026-09-08','Synthetic reversal');check($f->entry($paid)['payment_state']==='reversed','actual reversal state');denied(fn()=>$service->source($paid),'actual reversed entry rejected');
