if(EInvoiceValidator::configured()){$result=EInvoiceValidator::run($built['xml']);file_put_contents(__DIR__.'/../../.local/outgoing-validator-report.xml',$result['report']);check($result['state']==='valid','actual official KoSIT accepts generated UBL');$mixed=$f->createEntry(array_replace($data,['positions'=>[['description'=>'Rate 19','amount'=>'119','tax_rate'=>'19','sphere'=>'','account'=>''],['description'=>'Rate 7','amount'=>'107','tax_rate'=>'7','sphere'=>'','account'=>'']]]),$key());check(EInvoiceValidator::run($service->build($mixed,1,$fields)['xml'])['state']==='valid','actual mixed 7 and 19 percent invoice valid');$doc=$service->save($id,1,$fields);check($doc===$service->save($id,1,$fields),'same XML generation idempotent');check($db->query('SELECT COUNT(*) FROM einvoice_validations')->fetchColumn()==1,'original validation report preserved once');}else echo "SKIP native KoSIT: runtime unset\n";echo "$n outgoing invoice checks passed\n";
